//! "Trading Tech. Systems & Indicators for MetaStock" (research drive MetaStock/@Systems & Indicators/Trading Tech.
//! Systems & Ind. for Metastock/DBZ_Trading Tech., Systems and Indicators.pdf, 152 pp., Acrobat web capture of
//! 16 Apr 2001). It is a print of "peter's window on wallstreet formulas" (geocities.com/WallStreet/Floor/5645):
//! Peter's Window on WallStreet system list (A-Z pages) plus Equis Traders' Tips reprints for MetaStock.
//! Book id `mstt`. Systems are stored as printed and run by the formula engine in `msws` (same MetaStock
//! semantics); a system is Live only when an exit is printed and every function it calls is defined.
//! Page refs = PDF page. Transcription and checks: library/mstt/.
use crate::books::msws::{Book, Exec, Sys, EXEC_DEFAULT, EXEC_NEXT_OPEN};
use crate::connors::{Ctx, ParamDef, Params, StrategyDef, Trade};
#[allow(unused_imports)]
use crate::connors::Status::{Live, NeedsData, NotTestable};
use std::sync::OnceLock;

pub const BOOK: &str = "mstt";
/// Admitted ids (authors/lanea/elmtrader/decisions.json).
pub const REVIEWED_LANEA: &[&str] = &["mstt_four_bar_fear", "mstt_rainbow_chart_system"];
pub fn reviewed_lanea(id: &str) -> bool { REVIEWED_LANEA.contains(&id) }
const CONV: &str = "One position at a time; a position closes only by its own exit formula; an exit plus an opposite entry on one bar reverse; no same-direction re-entry on the exit bar; parameter side = 1/-1 runs one side alone. Indicators: MetaStock definitions (library/msws/README.md). India: runs on NIFTY 50 / indices instead of the stocks and futures it was written for (instrument swap only); price-point, price-level and volume-unit constants are applied literally.";
pub static MSTT: Book = Book { id: BOOK, sys: SYS, fml: FML, conv: CONV, cat: OnceLock::new(), par: OnceLock::new() };
pub fn catalogue() -> Vec<StrategyDef> { MSTT.catalogue() }
pub fn params(id: &str) -> Option<Vec<ParamDef>> { MSTT.params(id) }
pub fn run(id: &str, x: &Ctx, from: usize, to: usize, p: &Params) -> Option<Vec<Trade>> { MSTT.run(id, x, from, to, p) }
pub fn family_of(id: &str) -> Option<(&'static str, &'static str, &'static str)> { MSTT.family_of(id) }
#[allow(dead_code)]
fn _exec_type_check(e: Exec) -> Exec { e }

